import {ArrowRight,ArrowUpRight,BookOpen,Brain,CalendarDays,Check,CheckCircle2,ChevronLeft,ChevronRight,Clock3,Compass,Download,Focus,Lightbulb,ListTodo,Pause,Play,Plus,RotateCcw,Search,Sparkles,Target,Trash2,Trophy,X} from 'lucide-react';
