const fmt=(n:number)=>Number.isInteger(n)?String(n):n.toFixed(1);
const dateLabel=(value:string)=>new Date(value+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
const timeLabel=(value:string)=>new Date(value).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
const stamp=()=>new Date().toISOString();
function Head({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:React.ReactNode}){const [active,setActive]=useState(0);const route=window.location.pathname;const tabs:Record<string,string[]>={'/knowledge':['Overview','Subjects','Topic Details','Learning Path'],'/memory':['Overview','Review Queue','Flashcards','History'],'/exam-readiness':['Overview','Subjects','Study Priorities','Exams'],'/digital-twin':['Overview','Simulation','Trends','Goals'],'/adaptation':['Overview','Strategies','Comparison','History'],'/agent-history':['All Decisions','Accepted','Rejected','Details'],'/achievements':['Overview','Earned Badges','Milestones','History'],'/resources':['Discover','Notes','Videos','Practice','Books'],'/profile':['Overview','Academic','Goals','Activity'],'/settings':['General','Appearance','Study Preferences','Data & Privacy']};return <><div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action&&<div className="heading-action">{action}</div>}</div>{tabs[route]&&<nav className="reference-section-tabs" aria-label={`${title} sections`}>{tabs[route].map((name,i)=><button key={name} className={active===i?'active':''} onClick={()=>{setActive(i);document.querySelectorAll('main .card')[Math.min(i,document.querySelectorAll('main .card').length-1)]?.scrollIntoView({behavior:'smooth',block:'start'})}}>{name}</button>)}</nav>}</>}
function Card({title,subtitle,action,children,className=''}:{title?:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode;className?:string}){return <section className={'card '+className}>{(title||action)&&<div className="card-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}{children}</section>}
function Button({children,onClick,variant='primary',type='button',disabled=false}:{children:React.ReactNode;onClick?:()=>void;variant?:'primary'|'secondary'|'ghost'|'danger';type?:'button'|'submit';disabled?:boolean}){return <button type={type} disabled={disabled} className={'btn '+variant} onClick={onClick}>{children}</button>}
function Metric({label,value,note,icon:Icon}:{label:string;value:string;note:string;icon:any}){return <div className="metric"><div className="metric-top"><span>{label}</span><Icon size={18}/></div><strong>{value}</strong><small>{note}</small></div>}
function Empty({title,detail,action}:{title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><BookOpen size={22}/></div><b>{title}</b><p>{detail}</p>{action}</div>}
function ProgressBar({value}:{value:number}){return <div className="progress-track" role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}><div style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div>}
function SubjectSelect({value,onChange,d,all=false}:{value:string;onChange:(v:string)=>void;d:Data;all?:boolean}){return <select value={value} onChange={e=>onChange(e.target.value)}>{all&&<option value="all">All subjects</option>}{d.subjects.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>}
function Toast({message}:{message:string}){return message?<div className="toast" role="status"><CheckCircle2 size={17}/>{message}</div>:null}
function useToast(){const [message,setMessage]=useState('');const show=(s:string)=>{setMessage(s);setTimeout(()=>setMessage(''),3000)};return {message,show}}
export function Landing(){return <div className="landing"><header className="landing-nav"><Link className="landing-logo" to="/"><span className="brand-mark">N</span><b>NEXUS <small>STUDYOS</small></b></Link><nav><a href="#how">How it works</a><a href="#features">Features</a><Link to="/signin">Sign in</Link><Link className="btn primary" to="/signin">Get started <ArrowRight size={16}/></Link></nav></header><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="live-dot"/> AI-POWERED STUDY PLANNER</div><h1>Turn Your<br/><em>Study Journey</em><br/>Into Progress.</h1><p>NEXUS StudyOS understands you, adapts to changes, and helps you achieve your academic goals with a clear plan.</p><div className="hero-actions"><Link className="btn primary" to="/signin">Start Your Journey <ArrowRight size={18}/></Link><a className="btn secondary" href="#features">Watch Demo</a></div><div className="hero-proof"><div className="proof-line"/><span>PLAN WITH CLARITY · LEARN WITH PURPOSE</span></div></div><div className="hero-art" aria-label="Abstract orbit representing study time"><div className="orbit outer"><span className="orbit-label one">FOCUS</span><span className="orbit-label two">GROWTH</span></div><div className="orbit middle"/><div className="orbit inner"/><div className="orbit-core"><span>N</span></div><div className="hero-art-caption">01 / YOUR ACADEMIC UNIVERSE</div></div></section><section id="features" className="landing-section"><div className="section-top"><span className="eyebrow">THE NEXUS EXPERIENCE</span><h2>Everything connected.<br/><em>Nothing overwhelming.</em></h2></div><div className="feature-grid"><article><span className="feature-num">01</span><CalendarDays/><h3>A plan that moves with you</h3><p>Make a study schedule from your subjects, available hours, and deadlines. Rebuild it when your priorities change.</p></article><article><span className="feature-num">02</span><Brain/><h3>Learn what needs attention</h3><p>Track topic mastery and revision dates, then see where your next study session can make the most difference.</p></article><article><span className="feature-num">03</span><Compass/><h3>See the reason behind it</h3><p>Review proposed schedule changes and their assumptions before deciding whether to apply them.</p></article></div></section><section id="how" className="landing-how"><span className="eyebrow">A SIMPLE RHYTHM</span><div><h2>Plan. Learn.<br/><em>Adapt. Grow.</em></h2><p>Add your academic world once. NEXUS keeps your planner, progress, and recommendations connected through the same local records.</p><Link className="btn light" to="/signin">Open your workspace <ArrowRight size={17}/></Link></div><div className="how-steps"><span><b>01</b> Set your subjects and goals</span><span><b>02</b> Generate a realistic schedule</span><span><b>03</b> Study, review, and adjust</span></div></section><footer className="landing-footer"><b>NEXUS <small>STUDYOS</small></b><span>Made for a more considered way to learn.</span><Link to="/signin">Enter workspace <ArrowRight size={15}/></Link></footer></div>}
export function SignIn(){const navigate=useNavigate();const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[show,setShow]=useState(false),[error,setError]=useState(''),[mode,setMode]=useState<'sign-in'|'demo'>('sign-in');const {data}=useData();const enter=()=>navigate(data.student.onboarded?'/dashboard':'/onboarding');return <div className="auth"><div className="auth-aside"><Link className="landing-logo" to="/"><span className="brand-mark"/><b>NEXUS <small>StudyOS</small></b></Link><div className="auth-story"><span className="eyebrow">YOUR ACADEMIC COMPANION</span><h1>Plan Smarter.<br/><em>Learn Better.</em><br/>Achieve More.</h1><p>NEXUS StudyOS helps you plan, adapt, and stay on track—so you can focus on what truly matters.</p><div className="auth-benefits"><div><span>▱</span><b>Personalized Plans<small>Study schedules that adapt to you.</small></b></div><div><span>▥</span><b>Real Insights<small>Understand your progress clearly.</small></b></div><div><span>✧</span><b>Adaptive Support<small>Rebuild a plan when things change.</small></b></div><div><span>◎</span><b>Stay on Track<small>Turn your goals into real results.</small></b></div></div></div></div><div className="auth-form-wrap"><div className="auth-top-note">New here? <button onClick={()=>{setMode('demo');setError('')}}>Create Demo Account <ArrowRight size={16}/></button></div><form className="auth-form" onSubmit={e=>{e.preventDefault();setError('Email sign-in is not connected. Use Demo Mode to continue.')}}><h2>Welcome Back</h2><p>Continue your academic journey with NEXUS</p><div className="auth-tabs"><button type="button" className={mode==='sign-in'?'active':''} onClick={()=>setMode('sign-in')}>Sign In</button><button type="button" className={mode==='demo'?'active':''} onClick={()=>setMode('demo')}>Demo Mode</button></div>{mode==='sign-in'?<><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/></label><label>Password<div className="password-wrap"><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" required/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></div></label><div className="auth-meta"><label><input type="checkbox"/> Remember me</label><button type="button" onClick={()=>setError('Password recovery is unavailable in this local demo.')}>Forgot password?</button></div>{error&&<p className="error" role="alert">{error}</p>}<Button type="submit">Sign In <ArrowRight size={17}/></Button><div className="auth-separator">OR CONTINUE WITHOUT AN ACCOUNT</div><Button variant="secondary" onClick={enter}>Enter Demo Mode <ArrowRight size={17}/></Button></>:<><div className="auth-demo-note"><Lightbulb size={22}/><div><b>Explore the local workspace</b><p>No email or password is required. Your changes stay in this browser.</p></div></div><Button onClick={enter}>Enter StudyOS <ArrowRight size={17}/></Button></>}<Link className="btn secondary" to="/learn">Start Learning Now <ArrowRight size={17}/></Link><div className="auth-disclaimer"><Lightbulb size={18}/><span><b>This is a demo environment</b><small>No real account is required. Use demo mode to explore all features.</small></span></div></form></div></div>}
export function Onboarding(){const {data,update}=useData(),navigate=useNavigate();const [step,setStep]=useState(0),[form,setForm]=useState({...data.student}),[subjects,setSubjects]=useState(data.subjects),[newSubject,setNewSubject]=useState(''),[error,setError]=useState('');const steps=['Basic Info','Academic','Study Plan','Goals'];const next=()=>{if(step===0&&!form.name.trim()){setError('Please enter your name.');return}if(step===1&&!subjects.length){setError('Add at least one subject.');return}setError('');if(step<3){setStep(step+1);return}update(d=>({...d,student:{...form,onboarded:true},subjects}),{kind:'Profile',title:'Onboarding completed',detail:'Academic profile saved'});navigate('/dashboard')};return <div className="onboarding"><div className="onboard-top"><Link className="landing-logo" to="/"><span className="brand-mark">N</span><b>NEXUS <small>STUDYOS</small></b></Link><span>STEP {step+1} OF 4</span></div><div className="onboard-layout"><div className="onboard-side"><span className="eyebrow">LET'S BEGIN</span><h1>A Study Plan<br/><em>Built Around</em><br/>You.</h1><p>Tell us a bit about yourself so NEXUS can create a personalized study experience that adapts to your goals.</p><div className="step-list">{steps.map((x,i)=><div key={x} className={i===step?'current':i<step?'complete':''}><span>{i<step?<Check size={16}/>:String(i+1).padStart(2,'0')}</span>{x}</div>)}</div></div><div className="onboard-card"><div className="eyebrow">{steps[step].toUpperCase()}</div><h2>{['Tell us about yourself','What are you studying?','Find your study rhythm','What are you working toward?'][step]}</h2><p>{['This helps NEXUS personalize your experience.','Your subjects help NEXUS balance study time.','Set the time you can realistically protect for learning.','A clear intention makes every plan more useful.'][step]}</p>{step===0&&<div className="form-grid"><label>Full name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Academic level<select value={form.level} onChange={e=>setForm({...form,level:e.target.value})}><option>School</option><option>Undergraduate</option><option>Postgraduate</option><option>Other</option></select></label><label>Course<input value={form.course} onChange={e=>setForm({...form,course:e.target.value})}/></label><label>College or school<input value={form.college} onChange={e=>setForm({...form,college:e.target.value})} placeholder="Optional"/></label><label>Year<input value={form.year} onChange={e=>setForm({...form,year:e.target.value})}/></label></div>}{step===1&&<><div className="subject-pills">{subjects.map(s=><div key={s.id}>{s.name}<button aria-label={`Remove ${s.name}`} onClick={()=>setSubjects(subjects.filter(x=>x.id!==s.id))}><X size={15}/></button></div>)}</div><div className="inline-form"><input value={newSubject} onChange={e=>setNewSubject(e.target.value)} placeholder="Add a subject" onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();if(newSubject.trim()){setSubjects([...subjects,{id:uid(),name:newSubject.trim(),confidence:50,topics:[]}]);setNewSubject('')}}}}/><Button onClick={()=>{if(newSubject.trim()){setSubjects([...subjects,{id:uid(),name:newSubject.trim(),confidence:50,topics:[]}]);setNewSubject('')}}}><Plus size={16}/> Add</Button></div><p className="hint">You can add topics and adjust confidence later in Knowledge Constellation.</p></>}{step===2&&<div className="form-grid"><label>Daily study hours<input type="number" min="1" max="12" value={data.settings.dailyHours} onChange={e=>update(d=>({...d,settings:{...d.settings,dailyHours:Number(e.target.value)}}))}/></label><label>Preferred start time<input type="time" value={data.settings.preferredTime} onChange={e=>update(d=>({...d,settings:{...d.settings,preferredTime:e.target.value}}))}/></label><label>Session duration (minutes)<input type="number" min="15" max="180" value={data.settings.sessionMinutes} onChange={e=>update(d=>({...d,settings:{...d.settings,sessionMinutes:Number(e.target.value)}}))}/></label><label>Break duration (minutes)<input type="number" min="5" max="60" value={data.settings.breakMinutes} onChange={e=>update(d=>({...d,settings:{...d.settings,breakMinutes:Number(e.target.value)}}))}/></label></div>}{step===3&&<><label>Academic goal<textarea value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})} rows={4}/></label><div className="callout"><Lightbulb size={18}/><span>Your plan will use the subjects, exams, tasks, and study hours you add. You can change everything later.</span></div></>}{error&&<p className="error" role="alert">{error}</p>}<div className="onboard-actions"><Button variant="ghost" onClick={()=>setStep(Math.max(0,step-1))} disabled={step===0}><ChevronLeft size={17}/> Previous</Button><Button onClick={next}>{step===3?'Enter my workspace':'Continue'} <ArrowRight size={17}/></Button></div></div></div></div>}
export function Dashboard(){const {data:d,update}=useData(),navigate=useNavigate();const today=d.sessions.filter(s=>s.start.slice(0,10)===day());const upcoming=[...d.tasks.filter(t=>!t.done).map(t=>({title:t.title,date:t.due,subjectId:t.subjectId,type:'Task'})),...d.exams.map(e=>({title:e.title,date:e.date,subjectId:e.subjectId,type:'Exam'}))].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);const bars=Array.from({length:7},(_,i)=>({name:new Date(day(i-6)+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'}),hours:Math.round(d.sessions.filter(s=>s.done&&s.start.slice(0,10)===day(i-6)).reduce((a,s)=>a+s.minutes,0)/60*10)/10}));return <><Head eyebrow="YOUR ACADEMIC OVERVIEW" title={`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${d.student.name.split(' ')[0]}.`} description={`Here's the shape of your day · ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}`} action={<Button onClick={()=>navigate('/planner')}>Open planner <ArrowRight size={17}/></Button>}/><div className="welcome-banner"><div><span className="eyebrow">TODAY'S DIRECTION</span><h2>Make progress,<br/><em>one session at a time.</em></h2><p>{today.length?`${today.filter(s=>!s.done).length} study sessions planned for today.`:'Your calendar is open. Generate a plan to get started.'}</p><Button variant="secondary" onClick={()=>navigate('/planner')}>{today.length?'View today’s plan':'Build my study plan'} <ArrowRight size={16}/></Button></div><div className="banner-orbit"><div/><span>YOUR<br/>MOMENTUM</span></div></div><div className="metric-grid"><Metric label="Study hours" value={`${fmt(hours(d))}h`} note="Completed sessions" icon={Clock3}/><Metric label="Tasks completed" value={`${d.tasks.filter(t=>t.done).length}/${d.tasks.length}`} note="Across all subjects" icon={ListTodo}/><Metric label="Topic mastery" value={`${mastery(d)}%`} note="Average estimate" icon={Target}/><Metric label="Review queue" value={String(dueReviews(d).length)} note="Topics due for revision" icon={Brain}/></div><div className="grid two-one"><Card title="Today's study plan" subtitle="Your sessions, in order" action={<Link className="text-link" to="/planner">Open planner <ArrowRight size={15}/></Link>}>{today.length?<div className="session-list">{today.map(s=><div className="session-row" key={s.id}><span className="session-time">{timeLabel(s.start)}</span><div className="session-line"/><div><b>{s.title}</b><small>{subjectName(d,s.subjectId)} · {s.minutes} min</small></div><button className={'complete-button '+(s.done?'done':'')} title={s.done?'Completed':'Mark complete'} onClick={()=>update(x=>({...x,sessions:x.sessions.map(a=>a.id===s.id?{...a,done:!a.done}:a)}),{kind:'Study',title:s.done?'Session reopened':'Session completed',detail:s.title})}><Check size={16}/></button></div>)}</div>:<Empty title="A clear calendar" detail="Generate a study plan to fill your week with focused sessions." action={<Button variant="secondary" onClick={()=>navigate('/planner')}>Generate plan</Button>}/>}</Card><Card title="Subject mastery" subtitle="Estimated from topic records" action={<Link className="text-link" to="/knowledge">Explore <ArrowRight size={15}/></Link>}><div className="subject-bars">{d.subjects.map(s=><div key={s.id}><div><b>{s.name}</b><span>{Math.round(s.topics.reduce((a,t)=>a+t.mastery,0)/Math.max(1,s.topics.length))}%</span></div><ProgressBar value={s.topics.reduce((a,t)=>a+t.mastery,0)/Math.max(1,s.topics.length)}/></div>)}</div></Card></div><div className="grid two-one"><Card title="Study rhythm" subtitle="Completed hours over the last 7 days"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={bars}><CartesianGrid vertical={false} stroke="#e7e2d8"/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis allowDecimals={false} axisLine={false} tickLine={false}/><Tooltip/><Bar isAnimationActive={false} dataKey="hours" fill="#91a98d" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Card><Card title="Coming up" subtitle="Tasks and exams on the horizon">{upcoming.length?<div className="deadline-list">{upcoming.map((x,i)=><div key={i}><span className="date-tile"><b>{x.date.slice(8)}</b><small>{dateLabel(x.date).split(' ')[0]}</small></span><div><b>{x.title}</b><small>{subjectName(d,x.subjectId)} · {x.type}</small></div><ArrowUpRight size={16}/></div>)}</div>:<Empty title="Nothing due soon" detail="Add tasks or exams to see your next commitments."/>}</Card></div><Card className="recommendation" title="A thoughtful next step" subtitle="Based on your current topic records"><div className="rec-content"><div className="rec-icon"><Sparkles size={24}/></div><div><b>{dueReviews(d).length?`Review ${dueReviews(d)[0].name}`:'Keep your study rhythm going'}</b><p>{dueReviews(d).length?`${subjectName(d,dueReviews(d)[0].subjectId)} is in your review queue. A short revision can help reinforce it.`:'Your review queue is clear. Consider adding a new topic or planning your next session.'}</p></div><Button variant="secondary" onClick={()=>navigate('/memory')}>View memory engine <ArrowRight size={16}/></Button></div></Card></>}
export function Planner(){const {data:d,update}=useData(),{message,show}=useToast();const [view,setView]=useState(d.settings.view),[offset,setOffset]=useState(0),[filter,setFilter]=useState('all'),[editing,setEditing]=useState<string|null>(null),[form,setForm]=useState({title:'',subjectId:d.subjects[0]?.id||'',date:day(),time:'09:00',minutes:d.settings.sessionMinutes});const days=view==='Day'?1:view==='Week'?7:30;const start=day(offset*(view==='Day'?1:view==='Week'?7:30));const visible=d.sessions.filter(s=>s.start.slice(0,10)>=start&&s.start.slice(0,10)<=day(offset*(view==='Day'?1:view==='Week'?7:30)+days-1)&&(filter==='all'||s.subjectId===filter)).sort((a,b)=>a.start.localeCompare(b.start));const save=()=>{if(!form.title.trim())return show('Enter a session title');const startTime=new Date(`${form.date}T${form.time}:00`).toISOString();const candidate={id:editing||uid(),title:form.title,subjectId:form.subjectId,start:startTime,minutes:Number(form.minutes),done:false};const sessions=[...d.sessions.filter(s=>s.id!==editing),candidate];if(!validatePlan(sessions))return show('This time overlaps another session');update(x=>({...x,sessions}),{kind:'Schedule',title:editing?'Session updated':'Session added',detail:form.title});setEditing(null);show('Session saved')};const shift=(s:Session,days:number)=>{const dt=new Date(s.start);dt.setDate(dt.getDate()+days);const sessions=d.sessions.map(x=>x.id===s.id?{...x,start:dt.toISOString()}:x);if(!validatePlan(sessions))return show('The new time conflicts with another session');update(x=>({...x,sessions}),{kind:'Schedule',title:'Session rescheduled',detail:s.title});show('Session moved')};return <><Head eyebrow="MAKE SPACE FOR PROGRESS" title="Study planner" description="A realistic schedule built around your priorities and available time." action={<Button onClick={()=>{const sessions=generatePlan(d);update(x=>({...x,sessions}),{kind:'Schedule',title:'Study plan generated',detail:`${sessions.length} sessions in the current plan`});show('Your seven-day plan is ready')}}><Sparkles size={16}/> Generate study plan</Button>}/><div className="toolbar"><div className="segmented">{['Day','Week','Month'].map(x=><button key={x} className={view===x?'active':''} onClick={()=>{setView(x);setOffset(0);update(a=>({...a,settings:{...a.settings,view:x}}))}}>{x}</button>)}</div><div className="toolbar-right"><SubjectSelect d={d} all value={filter} onChange={setFilter}/><button className="icon" aria-label="Previous period" onClick={()=>setOffset(offset-1)}><ChevronLeft/></button><span className="period-label">{dateLabel(start)}</span><button className="icon" aria-label="Next period" onClick={()=>setOffset(offset+1)}><ChevronRight/></button></div></div><div className="grid two-one"><Card title={`${view} schedule`} subtitle={`${visible.length} sessions · ${fmt(visible.reduce((a,s)=>a+s.minutes,0)/60)} hours planned`} action={<Button variant="secondary" onClick={()=>{setForm({title:'',subjectId:d.subjects[0]?.id||'',date:day(),time:'09:00',minutes:d.settings.sessionMinutes});setEditing('new')}}><Plus size={16}/> Add session</Button>}>{visible.length?<div className="planner-list">{visible.map(s=><div className={'planner-item '+(s.done?'is-done':'')} key={s.id}><div className="planner-date"><b>{dateLabel(s.start.slice(0,10))}</b><small>{timeLabel(s.start)}</small></div><div className="planner-stripe"/><div className="planner-info"><b>{s.title}</b><small>{subjectName(d,s.subjectId)} · {s.minutes} min</small></div><div className="item-actions"><button title="Move one day later" onClick={()=>shift(s,1)}><ArrowRight size={16}/></button><button title="Edit session" onClick={()=>{setForm({title:s.title,subjectId:s.subjectId,date:s.start.slice(0,10),time:new Date(s.start).toTimeString().slice(0,5),minutes:s.minutes});setEditing(s.id)}}><CalendarDays size={16}/></button><button title={s.done?'Reopen':'Complete'} onClick={()=>update(x=>({...x,sessions:x.sessions.map(a=>a.id===s.id?{...a,done:!a.done}:a)}),{kind:'Study',title:s.done?'Session reopened':'Session completed',detail:s.title})}><Check size={16}/></button><button title="Delete session" onClick={()=>update(x=>({...x,sessions:x.sessions.filter(a=>a.id!==s.id)}),{kind:'Schedule',title:'Session removed',detail:s.title})}><Trash2 size={16}/></button></div></div>)}</div>:<Empty title="No sessions in this view" detail="Generate a plan or add a session to begin."/>}</Card><Card title="Your study capacity" subtitle="Current scheduling preferences"><div className="capacity"><strong>{d.settings.dailyHours}h</strong><span>available each day</span><ProgressBar value={Math.min(100,visible.length*d.settings.sessionMinutes/(d.settings.dailyHours*60*Math.max(1,days))*100)}/><p>{d.settings.sessionMinutes} min sessions · {d.settings.breakMinutes} min breaks</p><Link className="text-link" to="/settings">Adjust preferences <ArrowRight size={15}/></Link></div><div className="callout"><Lightbulb size={18}/> Generated plans prioritize weaker topics, imminent exams, and high priority tasks. They avoid overlapping sessions.</div></Card></div>{editing&&<div className="modal-back" onClick={()=>setEditing(null)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="card-head"><h2>{editing==='new'?'Add study session':'Edit study session'}</h2><button className="icon" onClick={()=>setEditing(null)}><X/></button></div><div className="form-grid"><label>Session title<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Subject<SubjectSelect d={d} value={form.subjectId} onChange={v=>setForm({...form,subjectId:v})}/></label><label>Date<input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Time<input type="time" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></label><label>Minutes<input type="number" min="15" max="240" value={form.minutes} onChange={e=>setForm({...form,minutes:Number(e.target.value)})}/></label></div><div className="modal-actions"><Button variant="ghost" onClick={()=>setEditing(null)}>Cancel</Button><Button onClick={save}>Save session</Button></div></div></div>}<Toast message={message}/></>}
export function Tasks(){const {data:d,update}=useData(),{message,show}=useToast();const [query,setQuery]=useState(''),[filter,setFilter]=useState('All'),[editing,setEditing]=useState<string|null>(null),[natural,setNatural]=useState(''),[form,setForm]=useState<Omit<Task,'id'|'created'|'done'>>({title:'',subjectId:d.subjects[0]?.id||'',due:day(3),priority:'Medium',category:'Assignment'});const list=d.tasks.filter(t=>(filter==='All'||(filter==='Completed'?t.done:filter==='Open'?!t.done:t.category===filter))&&`${t.title} ${subjectName(d,t.subjectId)}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.due.localeCompare(b.due));const save=()=>{if(!form.title.trim())return show('Enter a task title');update(x=>({...x,tasks:editing&&editing!=='new'?x.tasks.map(t=>t.id===editing?{...t,...form}:t):[{...form,id:uid(),created:stamp(),done:false},...x.tasks]}),{kind:'Task',title:editing==='new'?'Task added':'Task updated',detail:form.title});setEditing(null);show('Task saved')};const parse=()=>{if(!natural.trim())return;const lower=natural.toLowerCase();const subject=d.subjects.find(s=>lower.includes(s.name.toLowerCase()));const dateMatch=natural.match(/\d{4}-\d{2}-\d{2}/);setForm({title:natural.replace(dateMatch?.[0]||'','').trim(),subjectId:subject?.id||d.subjects[0]?.id||'',due:dateMatch?.[0]||day(lower.includes('tomorrow')?1:3),priority:lower.includes('urgent')?'High':'Medium',category:'Assignment'});setEditing('new')};return <><Head eyebrow="STAY AHEAD OF WHAT'S NEXT" title="Tasks & deadlines" description="Bring every commitment into focus, then make progress one step at a time." action={<Button onClick={()=>{setForm({title:'',subjectId:d.subjects[0]?.id||'',due:day(3),priority:'Medium',category:'Assignment'});setEditing('new')}}><Plus size={17}/> Add task</Button>}/><div className="metric-grid three"><Metric label="Open tasks" value={String(d.tasks.filter(t=>!t.done).length)} note="Ready for action" icon={ListTodo}/><Metric label="Completed" value={String(d.tasks.filter(t=>t.done).length)} note="All time" icon={CheckCircle2}/><Metric label="Due this week" value={String(d.tasks.filter(t=>!t.done&&t.due<=day(7)).length)} note="Next seven days" icon={CalendarDays}/></div><div className="grid two-one"><Card title="Your tasks" subtitle="Search and filter your academic work"><div className="toolbar"><div className="search-field"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search tasks..."/></div><select value={filter} onChange={e=>setFilter(e.target.value)}>{['All','Open','Completed','Assignment','Study','Revision','Exam','Project'].map(x=><option key={x}>{x}</option>)}</select></div>{list.length?<div className="rr-table-scroll"><table className="rx-task-table"><thead><tr><th>Task</th><th>Subject</th><th>Type</th><th>Priority</th><th>Due Date</th><th>Status</th><th>Actions</th></tr></thead><tbody>{list.map(t=><tr key={t.id}><td><label><input type="checkbox" checked={t.done} onChange={()=>update(x=>({...x,tasks:x.tasks.map(a=>a.id===t.id?{...a,done:!a.done}:a)}),{kind:'Task',title:t.done?'Task reopened':'Task completed',detail:t.title})}/><b className={t.done?'strike':''}>{t.title}</b></label></td><td><span className="rr-badge">{subjectName(d,t.subjectId)}</span></td><td>{t.category}</td><td><span className={'priority '+t.priority.toLowerCase()}>{t.priority}</span></td><td>{dateLabel(t.due)}</td><td><span className="rr-badge">{t.done?'Completed':t.status==='in-progress'?'In Progress':'To Do'}</span></td><td><button className="icon" aria-label="Edit task" onClick={()=>{setForm({title:t.title,subjectId:t.subjectId,due:t.due,priority:t.priority,category:t.category});setEditing(t.id)}}><CalendarDays size={16}/></button><button className="icon" aria-label="Delete task" onClick={()=>update(x=>({...x,tasks:x.tasks.filter(a=>a.id!==t.id)}),{kind:'Task',title:'Task deleted',detail:t.title})}><Trash2 size={16}/></button></td></tr>)}</tbody></table></div>:<Empty title="No matching tasks" detail="Try another filter or add a task."/>}</Card><div className="stack"><Card title="Quick capture" subtitle="Describe a task, then review it before saving"><textarea rows={4} value={natural} onChange={e=>setNatural(e.target.value)} placeholder="Complete calculus worksheet tomorrow, urgent"/><Button variant="secondary" onClick={parse}>Review task <ArrowRight size={16}/></Button><p className="hint">Dates in YYYY-MM-DD and subject names are recognized locally.</p></Card><Card title="Next deadlines" subtitle="Your upcoming commitments"><div className="compact-list">{d.tasks.filter(t=>!t.done).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4).map(t=><div key={t.id}><span>{dateLabel(t.due)}</span><b>{t.title}</b></div>)}</div></Card></div></div>{editing&&<div className="modal-back" onClick={()=>setEditing(null)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="card-head"><h2>{editing==='new'?'Review new task':'Edit task'}</h2><button className="icon" onClick={()=>setEditing(null)}><X/></button></div><div className="form-grid"><label>Title<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Subject<SubjectSelect d={d} value={form.subjectId} onChange={v=>setForm({...form,subjectId:v})}/></label><label>Due date<input type="date" value={form.due} onChange={e=>setForm({...form,due:e.target.value})}/></label><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value as Task['priority']})}><option>Low</option><option>Medium</option><option>High</option></select></label><label>Category<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{['Assignment','Study','Revision','Exam','Project'].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="modal-actions"><Button variant="ghost" onClick={()=>setEditing(null)}>Cancel</Button><Button onClick={save}>Save task</Button></div></div></div>}<Toast message={message}/></>}
function Proposal({scenario,onDone}:{scenario?:string;onDone?:()=>void}){const {data:d,update}=useData(),{message,show}=useToast();const [selected,setSelected]=useState(scenario||'Missed study session'),[proposal,setProposal]=useState<Decision|null>(null);const scenarios=['Missed study session','Quiz score dropped','Exam moved earlier','New assignment added','Available study hours reduced'];const propose=()=>{const before=d.sessions,after=generatePlan(d,selected,selected==='Available study hours reduced'?Math.max(1,d.settings.dailyHours-1):undefined);if(!validatePlan(after))return show('Generated plan has a conflict');const reason=selected==='Available study hours reduced'?'Reduced daily hours; prioritized weak topics within the new capacity.':selected==='Quiz score dropped'?'Regenerated sessions around lower mastery topics.':selected==='Exam moved earlier'?'Regenerated the next seven days; update the exam date to change urgency.':selected==='New assignment added'?'Regenerated the plan using current high-priority tasks.':'Removed one future session and rebuilt the remaining schedule.';setProposal({id:uid(),at:stamp(),scenario:selected,reason,before,after,status:'proposed'})};const decide=(status:'accepted'|'rejected')=>{if(!proposal)return;update(x=>({...x,sessions:status==='accepted'?proposal.after:x.sessions,decisions:[{...proposal,status},...x.decisions]}),{kind:'Agent',title:`Proposal ${status}`,detail:proposal.scenario});setProposal(null);show(`Proposal ${status}`);onDone?.()};return <><div className="form-grid"><label>Choose a scenario<select value={selected} onChange={e=>setSelected(e.target.value)}>{scenarios.map(s=><option key={s}>{s}</option>)}</select></label></div><Button onClick={propose}><Sparkles size={16}/> Generate proposal</Button>{proposal&&<div className="proposal"><div className="callout"><Lightbulb size={19}/><span><b>Why this changed</b><br/>{proposal.reason}</span></div><div className="proposal-compare"><div><small>BEFORE</small><strong>{proposal.before.filter(s=>!s.done).length}</strong><span>future sessions</span></div><ArrowRight/><div><small>PROPOSED</small><strong>{proposal.after.filter(s=>!s.done).length}</strong><span>future sessions</span></div></div><p className="hint">Review the proposed plan before applying. Scheduling is deterministic and local.</p><div className="modal-actions"><Button variant="ghost" onClick={()=>decide('rejected')}>Reject</Button><Button onClick={()=>decide('accepted')}>Accept plan <Check size={16}/></Button></div></div>}<Toast message={message}/></>}
export function Agent(){const {data:d,update}=useData();return <><Head eyebrow="EXPLAINABLE ACADEMIC PLANNING" title="AI agent" description="Explore deterministic schedule proposals before changing your study plan."/><div className="workflow">{['Observe','Analyze','Prioritize','Plan','Act','Evaluate'].map((s,i)=><div key={s}><span>{String(i+1).padStart(2,'0')}</span><b>{s}</b>{i<5&&<ArrowRight size={17}/>}</div>)}</div><div className="grid two-one"><Card title="Explore an adaptation" subtitle="Your plan changes only when you accept"><Proposal/></Card><div className="stack"><Card title="Current academic picture" subtitle="Signals used by the planner"><div className="insight-list"><div><span>Topics due for review</span><b>{dueReviews(d).length}</b></div><div><span>Open high priority tasks</span><b>{d.tasks.filter(t=>!t.done&&t.priority==='High').length}</b></div><div><span>Daily study capacity</span><b>{d.settings.dailyHours}h</b></div><div><span>Upcoming exams</span><b>{d.exams.filter(e=>e.date>=day()).length}</b></div></div></Card><Card title="Restore a previous plan" subtitle="Use your latest accepted decision"><Button variant="secondary" disabled={!d.decisions.some(x=>x.status==='accepted')} onClick={()=>{const last=d.decisions.find(x=>x.status==='accepted');if(last)update(x=>({...x,sessions:last.before,decisions:[{...last,id:uid(),at:stamp(),scenario:'Restore previous plan',reason:'Restored the plan before the accepted proposal.',before:x.sessions,after:last.before,status:'accepted'},...x.decisions]}),{kind:'Agent',title:'Previous plan restored',detail:last.scenario})}}><RotateCcw size={16}/> Restore plan</Button></Card></div></div></>}
export function Analytics(){const {data:d}=useData();const [range,setRange]=useState(30),[subject,setSubject]=useState('all');const sessions=d.sessions.filter(s=>s.done&&new Date(s.start).getTime()>Date.now()-range*86400000&&(subject==='all'||s.subjectId===subject));const chart=Array.from({length:7},(_,i)=>({name:dateLabel(day(i-6)),hours:Math.round(sessions.filter(s=>s.start.slice(0,10)===day(i-6)).reduce((a,s)=>a+s.minutes,0)/6)/10}));const total=sessions.reduce((a,s)=>a+s.minutes,0)/60;return <><Head eyebrow="UNDERSTAND YOUR RHYTHM" title="Learning analytics" description="A clear view of how you study, drawn from your completed activity." action={<div className="toolbar-right"><select value={range} onChange={e=>setRange(Number(e.target.value))}><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option></select><SubjectSelect d={d} all value={subject} onChange={setSubject}/></div>}/><div className="metric-grid three"><Metric label="Study time" value={`${fmt(total)}h`} note="Selected period" icon={Clock3}/><Metric label="Sessions completed" value={String(sessions.length)} note="Selected period" icon={CheckCircle2}/><Metric label="Task completion" value={`${d.tasks.length?Math.round(d.tasks.filter(t=>t.done).length/d.tasks.length*100):0}%`} note="All recorded tasks" icon={ListTodo}/></div><div className="grid two-one"><Card title="Study time trend" subtitle="Completed hours in the last seven days"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart}><CartesianGrid vertical={false} stroke="#e7e2d8"/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area isAnimationActive={false} dataKey="hours" stroke="#173e2d" fill="#e5ebdd" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></Card><Card title="Time by subject" subtitle="Completed sessions in this period"><div className="subject-bars">{d.subjects.map(s=>{const h=sessions.filter(x=>x.subjectId===s.id).reduce((a,x)=>a+x.minutes,0)/60;return <div key={s.id}><div><b>{s.name}</b><span>{fmt(h)}h</span></div><ProgressBar value={total?100*h/total:0}/></div>})}</div></Card></div><Card title="Performance insight" subtitle="Based on the records currently available"><div className="callout"><Lightbulb size={18}/><span>{sessions.length?`You completed ${sessions.length} sessions in the selected period. Continue logging focus time to reveal a longer trend.`:'No completed sessions in this period yet. Finish a study session to begin tracking your rhythm.'}</span></div></Card></>}
export function Progress(){const {data:d}=useData();const completed=d.sessions.filter(s=>s.done).length,done=d.tasks.filter(t=>t.done).length,topics=d.subjects.flatMap(s=>s.topics),strong=topics.filter(t=>t.mastery>=80).length;return <><Head eyebrow="SEE HOW FAR YOU'VE COME" title="Your progress" description="The small steps that add up to a stronger academic foundation."/><div className="metric-grid"><Metric label="Overall mastery" value={`${mastery(d)}%`} note="Average topic estimate" icon={Target}/><Metric label="Study sessions" value={String(completed)} note="Completed" icon={Focus}/><Metric label="Tasks finished" value={String(done)} note="Across your workspace" icon={CheckCircle2}/><Metric label="Strong topics" value={String(strong)} note="Mastery of 80% or more" icon={Trophy}/></div><div className="grid two-one"><Card title="Subject journey" subtitle="Mastery across topics"><div className="subject-bars spacious">{d.subjects.map(s=><div key={s.id}><div><b>{s.name}</b><span>{s.topics.length} topics</span></div><ProgressBar value={s.topics.reduce((a,t)=>a+t.mastery,0)/Math.max(1,s.topics.length)}/></div>)}</div></Card><Card title="This week's goal" subtitle="Your preferred daily study capacity"><div className="goal-big"><strong>{fmt(d.sessions.filter(s=>s.done&&s.start.slice(0,10)>=day(-6)).reduce((a,s)=>a+s.minutes,0)/60)}h</strong><span>of {d.settings.dailyHours*7}h weekly capacity</span></div><ProgressBar value={d.sessions.filter(s=>s.done&&s.start.slice(0,10)>=day(-6)).reduce((a,s)=>a+s.minutes,0)/(d.settings.dailyHours*7*60)*100}/></Card></div><Card title="Learning journey" subtitle="Your most recent completed steps">{d.events.length?<div className="timeline">{d.events.slice(0,8).map(e=><div key={e.id}><span className="timeline-dot"/><div><small>{new Date(e.at).toLocaleDateString()} · {e.kind}</small><b>{e.title}</b><p>{e.detail}</p></div></div>)}</div>:<Empty title="Your story starts here" detail="Complete sessions and tasks to build your learning journey."/>}</Card></>}
export function FocusPage(){const {data:d,update}=useData(),{message,show}=useToast();const [now,setNow]=useState(Date.now());useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id)},[]);const f=d.focus,remaining=f.running&&f.end?Math.max(0,Math.ceil((f.end-now)/1000)):f.remaining;useEffect(()=>{if(f.running&&f.end&&remaining===0){update(x=>({...x,focus:{...x.focus,running:false,end:null,remaining:0}}),{kind:'Focus',title:'Focus timer finished',detail:f.objective||'Time is complete'})}},[remaining,f.running,f.end]);const setFocus=(patch:Partial<typeof f>)=>update(x=>({...x,focus:{...x.focus,...patch}}));const complete=()=>{const minutes=Math.max(1,Math.round((d.settings.sessionMinutes*60-remaining)/60));const s:Session={id:uid(),subjectId:f.subjectId,title:f.objective||'Focus session',start:stamp(),minutes,done:true};update(x=>({...x,sessions:[...x.sessions,s],focus:{...x.focus,running:false,end:null,remaining:x.settings.sessionMinutes*60},tasks:f.taskId?x.tasks.map(t=>t.id===f.taskId?{...t,done:true}:t):x.tasks}),{kind:'Study',title:'Focus session completed',detail:`${minutes} minutes · ${subjectName(d,f.subjectId)}`});show('Focus session saved')};return <><Head eyebrow="ONE THING AT A TIME" title="Focus mode" description="A quieter space for meaningful work. Your timer stays accurate when the tab is inactive."/><div className="grid two-one"><Card className="focus-card"><div className="focus-ring"><div><span>FOCUS SESSION</span><strong>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</strong><small>{subjectName(d,f.subjectId)}</small></div></div><div className="focus-controls"><Button variant="secondary" onClick={()=>{if(f.running)setFocus({running:false,end:null,remaining});else setFocus({running:true,end:Date.now()+remaining*1000})}}>{f.running?<><Pause size={17}/> Pause</>:<><Play size={17}/> {remaining===d.settings.sessionMinutes*60?'Start':'Resume'}</>}</Button><Button variant="ghost" onClick={()=>setFocus({running:false,end:null,remaining:d.settings.sessionMinutes*60})}><RotateCcw size={17}/> Reset</Button><Button onClick={complete}><Check size={17}/> Complete session</Button></div></Card><div className="stack"><Card title="Session intention" subtitle="Choose what you'll work on"><div className="form-grid"><label>Subject<SubjectSelect d={d} value={f.subjectId} onChange={v=>setFocus({subjectId:v})}/></label><label>Related task<select value={f.taskId} onChange={e=>setFocus({taskId:e.target.value})}><option value="">No task</option>{d.tasks.filter(t=>!t.done).map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></label><label className="full">Objective<input value={f.objective} onChange={e=>setFocus({objective:e.target.value})} placeholder="What will you finish?"/></label></div></Card><Card title="Timer options" subtitle="Choose a rhythm that works"><div className="chip-row">{[[25,'Short focus'],[50,'Deep work'],[5,'Short break'],[15,'Long break']].map(([n,label])=><button key={n} onClick={()=>setFocus({running:false,end:null,remaining:Number(n)*60})}>{label} · {n}m</button>)}</div></Card><Card title="Today in focus" subtitle="From completed sessions"><div className="goal-big"><strong>{fmt(d.sessions.filter(s=>s.done&&s.start.slice(0,10)===day()).reduce((a,s)=>a+s.minutes,0)/60)}h</strong><span>completed today</span></div></Card></div></div><Toast message={message}/></>}
export function Knowledge(){const {data:d,update}=useData(),{message,show}=useToast();const [subject,setSubject]=useState('all'),[selected,setSelected]=useState(''),[name,setName]=useState(''),[topicName,setTopicName]=useState('');const subjects=d.subjects.filter(s=>subject==='all'||s.id===subject);const topic=d.subjects.flatMap(s=>s.topics.map(t=>({...t,subject:s}))).find(t=>t.id===selected);return <><Head eyebrow="THE SHAPE OF WHAT YOU KNOW" title="Knowledge constellation" description="Explore subjects, topics, and the paths that connect them."/><div className="toolbar"><SubjectSelect d={d} all value={subject} onChange={setSubject}/><div className="inline-form"><input value={name} onChange={e=>setName(e.target.value)} placeholder="New subject"/><Button variant="secondary" onClick={()=>{if(!name.trim())return;update(x=>({...x,subjects:[...x.subjects,{id:uid(),name:name.trim(),confidence:50,topics:[]}]}),{kind:'Knowledge',title:'Subject added',detail:name});setName('');show('Subject added')}}><Plus size={16}/> Add subject</Button></div></div><div className="grid two-one"><Card title="Knowledge map" subtitle="Select a topic to inspect its learning path"><div className="knowledge-map">{subjects.map((s,i)=><div className="knowledge-cluster" key={s.id} style={{gridArea:`${Math.floor(i/2)+1} / ${i%2+1}`}}><div className="subject-node">{s.name}</div><div className="topic-nodes">{s.topics.map(t=><button key={t.id} className={selected===t.id?'selected':''} onClick={()=>setSelected(t.id)} title={`${t.name}: ${t.mastery}% mastery`}><span style={{background:t.mastery<60?'#c8a878':'#91a98d'}}/>{t.name}</button>)}</div></div>)}</div><p className="hint">This 2D map uses your actual subject, topic, and prerequisite records. A 3D view is not yet implemented.</p></Card><div className="stack"><Card title={topic?.name||'Topic details'} subtitle={topic?topic.subject.name:'Select a topic from the map'}>{topic?<><div className="goal-big"><strong>{topic.mastery}%</strong><span>estimated mastery</span></div><ProgressBar value={topic.mastery}/><div className="insight-list"><div><span>Prerequisite</span><b>{topic.prerequisite?topic.subject.topics.find(t=>t.id===topic.prerequisite)?.name||'Unknown':'None recorded'}</b></div><div><span>Reviews</span><b>{topic.reviews}</b></div></div></>:<Empty title="Choose a topic" detail="See its mastery and prerequisite relationship here."/>}</Card><Card title="Add a topic" subtitle="Create a concept in your knowledge map"><div className="inline-form"><input value={topicName} onChange={e=>setTopicName(e.target.value)} placeholder="Topic name"/><Button onClick={()=>{if(!topicName.trim())return;const target=subject==='all'?d.subjects[0]?.id:subject;if(!target)return;update(x=>({...x,subjects:x.subjects.map(s=>s.id===target?{...s,topics:[...s.topics,{id:uid(),name:topicName.trim(),mastery:50,reviews:0,interval:1}]}:s)}),{kind:'Knowledge',title:'Topic added',detail:topicName});setTopicName('');show('Topic added')}}><Plus size={16}/></Button></div><p className="hint">New topics start with a neutral 50% estimate.</p></Card></div></div><Toast message={message}/></>}
export function Memory(){const {data:d,update}=useData(),{message,show}=useToast();const [selected,setSelected]=useState('');const topics=d.subjects.flatMap(s=>s.topics.map(t=>({...t,subject:s}))),due=topics.filter(t=>!t.lastReview||new Date(t.lastReview).getTime()+t.interval*86400000<=Date.now()).sort((a,b)=>retention(a)-retention(b));const current=topics.find(t=>t.id===selected)||due[0];const rate=(rating:'Again'|'Hard'|'Good'|'Easy')=>{if(!current)return;const intervals={Again:1,Hard:2,Good:4,Easy:7},gain={Again:-8,Hard:1,Good:4,Easy:7};update(x=>({...x,subjects:x.subjects.map(s=>({...s,topics:s.topics.map(t=>t.id===current.id?{...t,lastReview:stamp(),reviews:t.reviews+1,interval:intervals[rating]*(t.reviews+1),mastery:Math.min(100,Math.max(0,t.mastery+gain[rating]))}:t)}))}),{kind:'Revision',title:`Reviewed ${current.name}`,detail:`Rated ${rating}`});setSelected('');show('Review recorded')};return <><Head eyebrow="REMEMBER WHAT MATTERS" title="Memory engine" description="A deterministic review queue based on your revision history and estimated retention."/><div className="metric-grid three"><Metric label="Due for review" value={String(due.length)} note="Ready now" icon={Brain}/><Metric label="Total reviews" value={String(topics.reduce((a,t)=>a+t.reviews,0))} note="All topics" icon={RotateCcw}/><Metric label="Average retention" value={`${Math.round(topics.reduce((a,t)=>a+retention(t),0)/Math.max(1,topics.length))}%`} note="Model estimate" icon={Target}/></div><div className="grid two-one"><Card title="Review queue" subtitle="Lower estimated retention appears first">{due.length?<div className="compact-list">{due.map(t=><button className={'review-row '+(current?.id===t.id?'active':'')} key={t.id} onClick={()=>setSelected(t.id)}><div><b>{t.name}</b><small>{t.subject.name} · {t.reviews} reviews</small></div><span>{retention(t)}% estimated</span></button>)}</div>:<Empty title="All caught up" detail="Your next reviews will appear here when due."/>}</Card><Card title={current?`Review ${current.name}`:'No review selected'} subtitle="How well did you recall this topic?">{current?<><p className="review-prompt">Pause and recall the key ideas from {current.name}. Then rate how easily you remembered them.</p><div className="chip-row">{(['Again','Hard','Good','Easy'] as const).map(r=><button key={r} onClick={()=>rate(r)}>{r}</button>)}</div><p className="hint">Retention is an estimate from time, mastery, and review interval; it is not a measurement of memory.</p></>:<Empty title="Queue complete" detail="Add topics in Knowledge Constellation to keep learning."/>}</Card></div><Toast message={message}/></>}
export function ExamReadiness(){const {data:d,update}=useData(),{message,show}=useToast();const [selected,setSelected]=useState(d.exams[0]?.id||''),[title,setTitle]=useState(''),[subject,setSubject]=useState(d.subjects[0]?.id||''),[date,setDate]=useState(day(14));const exam=d.exams.find(e=>e.id===selected),topics=d.subjects.find(s=>s.id===exam?.subjectId)?.topics||[];const score=exam?readiness(d,exam.subjectId):0;const daysLeft=exam?Math.max(0,Math.ceil((new Date(exam.date).getTime()-Date.now())/86400000)):0;return <><Head eyebrow="PREPARE WITH PERSPECTIVE" title="Exam readiness" description="An estimated preparation view grounded in your topics and revision records."/><div className="toolbar"><select value={selected} onChange={e=>setSelected(e.target.value)}>{d.exams.map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select></div><div className="grid two-one"><Card title={exam?.title||'No exam selected'} subtitle={exam?`${subjectName(d,exam.subjectId)} · ${dateLabel(exam.date)}`:'Add an exam to begin'}>{exam?<><div className="readiness-score"><strong>{score}%</strong><div><b>Estimated readiness</b><p>75% topic mastery + 25% revision coverage</p></div></div><ProgressBar value={score}/><div className="insight-list"><div><span>Days until exam</span><b>{daysLeft}</b></div><div><span>Topics tracked</span><b>{topics.length}</b></div><div><span>Topics reviewed</span><b>{topics.filter(t=>t.reviews>0).length}</b></div></div><p className="hint">This is a planning estimate, not a predicted mark.</p></>:<Empty title="Add your first exam" detail="Use the form to start tracking readiness."/>}</Card><div className="stack"><Card title="Study priorities" subtitle="Topics with the most room to grow">{topics.length?<div className="compact-list">{[...topics].sort((a,b)=>a.mastery-b.mastery).map(t=><div key={t.id}><span>{t.mastery}%</span><b>{t.name}</b></div>)}</div>:<Empty title="No topics yet" detail="Add topics to this subject in Knowledge Constellation."/>}</Card><Card title="Add an exam" subtitle="Keep your assessment dates current"><div className="form-grid"><label>Exam title<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Subject<SubjectSelect d={d} value={subject} onChange={setSubject}/></label><label>Date<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label></div><Button onClick={()=>{if(!title.trim())return show('Enter an exam title');const e:Exam={id:uid(),title:title.trim(),subjectId:subject,date};update(x=>({...x,exams:[...x.exams,e]}),{kind:'Exam',title:'Exam added',detail:e.title});setSelected(e.id);setTitle('');show('Exam added')}}><Plus size={16}/> Add exam</Button></Card></div></div><Toast message={message}/></>}
export function DigitalTwin(){const {data:d}=useData();const [scenario,setScenario]=useState('Increase study hours'),[amount,setAmount]=useState(2);const current=mastery(d),delta=scenario==='Increase study hours'?amount*2:scenario==='Miss several study days'?-amount*3:scenario==='Improve quiz scores'?amount*2:scenario==='Focus on weak subjects'?amount:0;const projected=Math.max(0,Math.min(100,current+delta));const chart=Array.from({length:6},(_,i)=>({week:`Week ${i}`,current,scenario:Math.round(current+delta*i/5)}));return <><Head eyebrow="EXPLORE POSSIBLE FUTURES" title="Academic digital twin" description="Change an assumption to see a simple, transparent projection from your current records."/><div className="grid two-one"><Card title="What if you changed your routine?" subtitle="Projection uses explicit assumptions"><div className="form-grid"><label>Scenario<select value={scenario} onChange={e=>setScenario(e.target.value)}>{['Increase study hours','Miss several study days','Improve quiz scores','Focus on weak subjects'].map(x=><option key={x}>{x}</option>)}</select></label><label>Change amount<input type="range" min="1" max="5" value={amount} onChange={e=>setAmount(Number(e.target.value))}/><span>{amount} {scenario.includes('days')?'days':'units'}</span></label></div><div className="proposal-compare"><div><small>CURRENT</small><strong>{current}%</strong><span>topic mastery estimate</span></div><ArrowRight/><div><small>SIMULATED</small><strong>{projected}%</strong><span>illustrative outcome</span></div></div><p className="hint">Model assumption: each unit changes average mastery by {scenario==='Miss several study days'?'-3':scenario==='Focus on weak subjects'?'+1':'+2'} points. This is an illustrative what-if model, not a grade forecast.</p></Card><Card title="Possible trajectory" subtitle="Six-week illustrative view"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chart}><CartesianGrid vertical={false} stroke="#e7e2d8"/><XAxis dataKey="week" axisLine={false} tickLine={false}/><YAxis domain={[0,100]} axisLine={false} tickLine={false}/><Tooltip/><Area isAnimationActive={false} dataKey="scenario" stroke="#173e2d" fill="#e5ebdd" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></Card></div></>}
export function Adaptation(){const {data:d}=useData();return <><Head eyebrow="TRY A DIFFERENT PATH" title="Adaptation lab" description="Experiment with scheduling scenarios and review a feasible plan before applying it."/><div className="metric-grid three"><Metric label="Current sessions" value={String(d.sessions.filter(s=>!s.done).length)} note="Future plan" icon={CalendarDays}/><Metric label="Daily capacity" value={`${d.settings.dailyHours}h`} note="Available study time" icon={Clock3}/><Metric label="Weak topics" value={String(d.subjects.flatMap(s=>s.topics).filter(t=>t.mastery<60).length)} note="Below 60% mastery" icon={Target}/></div><Card title="Strategy workbench" subtitle="The same scheduling engine powers planner and agent proposals"><Proposal/></Card></>}
export function AgentHistory(){const {data:d}=useData();const [query,setQuery]=useState(''),[status,setStatus]=useState('All'),[selected,setSelected]=useState('');const list=d.decisions.filter(x=>(status==='All'||x.status===status.toLowerCase())&&x.scenario.toLowerCase().includes(query.toLowerCase()));const item=list.find(x=>x.id===selected)||list[0];return <><Head eyebrow="EVERY DECISION, EXPLAINED" title="Agent history" description="A traceable record of schedule proposals and the choices you made."/><div className="grid two-one"><Card title="Decision timeline" subtitle={`${list.length} recorded decisions`}><div className="toolbar"><div className="search-field"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search decisions"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>All</option><option>Accepted</option><option>Rejected</option></select></div>{list.length?<div className="compact-list">{list.map(x=><button className={'review-row '+(item?.id===x.id?'active':'')} key={x.id} onClick={()=>setSelected(x.id)}><div><b>{x.scenario}</b><small>{new Date(x.at).toLocaleString()}</small></div><span className="status-pill">{x.status}</span></button>)}</div>:<Empty title="No decisions yet" detail="Explore a scenario in AI Agent to create the first record."/>}</Card><Card title="Decision details" subtitle="What changed, and why">{item?<><div className="callout"><Lightbulb size={18}/>{item.reason}</div><div className="insight-list"><div><span>Status</span><b>{item.status}</b></div><div><span>Before</span><b>{item.before.length} sessions</b></div><div><span>Proposed</span><b>{item.after.length} sessions</b></div></div><p className="hint">Expected impact is the proposed schedule difference. No outcome is claimed until study sessions are completed.</p></>:<Empty title="Select a decision" detail="Decision reasoning will appear here."/>}</Card></div></>}
export function Profile(){const {data:d,update}=useData(),{message,show}=useToast();const [form,setForm]=useState(d.student);return <><Head eyebrow="YOUR ACADEMIC IDENTITY" title="Student profile" description="Keep the details behind your study plan up to date."/><div className="profile-banner"><div className="avatar large">{form.name.slice(0,1)}</div><div><h2>{form.name}</h2><p>{form.course} {form.college&&`· ${form.college}`}</p></div><span>LOCAL DEMO PROFILE</span></div><div className="grid two-one"><Card title="Personal details" subtitle="Shared with onboarding and your workspace"><div className="form-grid"><label>Name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Academic level<input value={form.level} onChange={e=>setForm({...form,level:e.target.value})}/></label><label>Course<input value={form.course} onChange={e=>setForm({...form,course:e.target.value})}/></label><label>College<input value={form.college} onChange={e=>setForm({...form,college:e.target.value})}/></label><label>Year<input value={form.year} onChange={e=>setForm({...form,year:e.target.value})}/></label><label className="full">Academic goal<textarea rows={3} value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/></label></div><Button onClick={()=>{if(!form.name.trim())return show('Name is required');update(x=>({...x,student:form}),{kind:'Profile',title:'Profile updated',detail:form.name});show('Profile saved')}}>Save changes</Button></Card><div className="stack"><Card title="Learning snapshot" subtitle="From your recorded activity"><div className="insight-list"><div><span>Study hours</span><b>{fmt(hours(d))}h</b></div><div><span>Completed tasks</span><b>{d.tasks.filter(t=>t.done).length}</b></div><div><span>Subjects</span><b>{d.subjects.length}</b></div><div><span>Average mastery</span><b>{mastery(d)}%</b></div></div></Card><Card title="Your direction" subtitle="The goal guiding your work"><p className="quote">“{form.goal||'Set an academic goal to give your plan direction.'}”</p></Card></div></div><Toast message={message}/></>}
export function SettingsPage(){const {data:d,update}=useData(),{message,show}=useToast();const s=d.settings;const set=(patch:Partial<typeof s>)=>update(x=>({...x,settings:{...x.settings,...patch}}));const exportData=()=>{const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexus-studyos-data.json';a.click();URL.revokeObjectURL(a.href);show('Data exported')};return <><Head eyebrow="MAKE IT YOURS" title="Settings" description="Shape your study rhythm and manage your local workspace."/><div className="settings-grid"><Card title="Study preferences" subtitle="Used when NEXUS builds a plan"><div className="form-grid"><label>Daily study hours<input type="number" min="1" max="12" value={s.dailyHours} onChange={e=>set({dailyHours:Number(e.target.value)})}/></label><label>Session duration (min)<input type="number" min="15" max="180" value={s.sessionMinutes} onChange={e=>set({sessionMinutes:Number(e.target.value)})}/></label><label>Break duration (min)<input type="number" min="5" max="60" value={s.breakMinutes} onChange={e=>set({breakMinutes:Number(e.target.value)})}/></label><label>Preferred study time<input type="time" value={s.preferredTime} onChange={e=>set({preferredTime:e.target.value})}/></label><label>Default planner view<select value={s.view} onChange={e=>set({view:e.target.value})}><option>Day</option><option>Week</option><option>Month</option></select></label></div></Card><Card title="Appearance" subtitle="Choose a comfortable interface"><div className="form-grid"><label>Theme<select value={s.theme} onChange={e=>set({theme:e.target.value})}><option value="light">Warm light</option><option value="dark">Deep forest</option></select></label></div></Card><Card title="Reminders" subtitle="Local preferences for future features"><label className="switch-row"><div><b>Study reminders</b><small>Preference saved in this browser; system notifications are not connected.</small></div><input type="checkbox" checked={s.reminders} onChange={e=>set({reminders:e.target.checked})}/></label></Card><Card title="Data & privacy" subtitle="Your data stays in this browser"><p className="muted">This demo uses localStorage. Clearing browser data removes your study records. No backend or account sync is connected.</p><div className="button-row"><Button variant="secondary" onClick={exportData}><Download size={16}/> Export data</Button><Button variant="danger" onClick={()=>{if(!window.confirm('Clear completed study sessions and activity history?'))return;update(x=>({...x,sessions:x.sessions.filter(a=>!a.done),events:[]}));show('Study history cleared')}}><Trash2 size={16}/> Clear study history</Button></div></Card></div><Toast message={message}/></>}
export function ActivityPage(){const {data:d}=useData();const [kind,setKind]=useState('All'),[query,setQuery]=useState('');const items=d.events.filter(x=>(kind==='All'||x.kind===kind)&&`${x.title} ${x.detail}`.toLowerCase().includes(query.toLowerCase()));return <><Head eyebrow="THE WORK BEHIND THE GROWTH" title="Activity history" description="A chronological record of what you have done in your workspace."/><Card title="Your timeline" subtitle={`${items.length} events shown`}><div className="toolbar"><div className="search-field"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search activity"/></div><select value={kind} onChange={e=>setKind(e.target.value)}>{['All','Study','Task','Schedule','Agent','Revision','Knowledge','Profile','Exam'].map(x=><option key={x}>{x}</option>)}</select></div>{items.length?<div className="timeline">{items.map(e=><div key={e.id}><span className="timeline-dot"/><div><small>{new Date(e.at).toLocaleString()} · {e.kind}</small><b>{e.title}</b><p>{e.detail}</p></div></div>)}</div>:<Empty title="No activity matches" detail="Complete a task or study session to start your timeline."/>}</Card></>}
export function Achievements(){const {data:d}=useData();const sessions=d.sessions.filter(s=>s.done).length,tasks=d.tasks.filter(t=>t.done).length,reviews=d.subjects.flatMap(s=>s.topics).reduce((a,t)=>a+t.reviews,0);const badges=[{title:'First focus',detail:'Complete one study session',value:sessions,goal:1},{title:'Steady learner',detail:'Complete five study sessions',value:sessions,goal:5},{title:'Task finisher',detail:'Complete three academic tasks',value:tasks,goal:3},{title:'Memory keeper',detail:'Record five topic reviews',value:reviews,goal:5}];const earned=badges.filter(b=>b.value>=b.goal).length;return <><Head eyebrow="CELEBRATE THE REAL WORK" title="Achievements" description="Milestones earned through your recorded study activity."/><div className="metric-grid three"><Metric label="Badges earned" value={`${earned}/${badges.length}`} note="Based on real actions" icon={Trophy}/><Metric label="Study sessions" value={String(sessions)} note="Completed" icon={Focus}/><Metric label="Topic reviews" value={String(reviews)} note="Recorded" icon={Brain}/></div><div className="achievement-grid">{badges.map(b=><div className={'achievement '+(b.value>=b.goal?'earned':'')} key={b.title}><div className="achievement-icon"><Trophy size={25}/></div><span>{b.value>=b.goal?'EARNED':'IN PROGRESS'}</span><h2>{b.title}</h2><p>{b.detail}</p><ProgressBar value={b.value/b.goal*100}/><small>{Math.min(b.value,b.goal)} of {b.goal}</small></div>)}</div></>}
export function Resources(){const {data:d}=useData();const [query,setQuery]=useState(''),[type,setType]=useState('All');const resources=[{title:'OpenStax textbooks',type:'Books',detail:'Free, peer-reviewed textbooks across mathematics, science, and more.',url:'https://openstax.org/subjects'},{title:'Khan Academy',type:'Practice',detail:'Lessons and practice for mathematics, sciences, and computing.',url:'https://www.khanacademy.org/'},{title:'MIT OpenCourseWare',type:'Courses',detail:'Open course materials from MIT.',url:'https://ocw.mit.edu/'},{title:'3Blue1Brown',type:'Videos',detail:'Visual explanations of mathematics and related ideas.',url:'https://www.3blue1brown.com/'},{title:'Paul’s Online Math Notes',type:'Notes',detail:'Calculus and algebra notes with worked examples.',url:'https://tutorial.math.lamar.edu/'},{title:'GeeksforGeeks',type:'Practice',detail:'Computer science explanations and practice.',url:'https://www.geeksforgeeks.org/'}].filter(r=>(type==='All'||r.type===type)&&`${r.title} ${r.detail}`.toLowerCase().includes(query.toLowerCase()));return <><Head eyebrow="GO DEEPER, LEARN BETTER" title="Resources" description="A small curated set of public learning links. Availability is managed by their publishers."/><div className="toolbar"><div className="search-field"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search resources"/></div><select value={type} onChange={e=>setType(e.target.value)}>{['All','Books','Practice','Courses','Videos','Notes'].map(x=><option key={x}>{x}</option>)}</select></div><div className="resource-grid">{resources.map(r=><a className="resource-card" href={r.url} target="_blank" rel="noopener noreferrer" key={r.title}><div className="resource-icon"><BookOpen size={23}/></div><span>{r.type.toUpperCase()}</span><h2>{r.title}</h2><p>{r.detail}</p><b>Visit resource <ArrowUpRight size={16}/></b></a>)}</div><Card title="Your subjects" subtitle="Use your topic list to choose what to explore next"><div className="subject-pills">{d.subjects.map(s=><div key={s.id}>{s.name}</div>)}</div></Card></>}


